from __future__ import annotations

import io
import tarfile
from typing import TYPE_CHECKING

import pytest
import typer
from ds.cli import ui_fonts
from fontTools.ttLib import TTFont

if TYPE_CHECKING:
    from pathlib import Path


def _archive(path: Path, names: list[str]) -> Path:
    with tarfile.open(path, "w:xz") as tar:
        for name in names:
            data = name.encode()
            info = tarfile.TarInfo(f"JetBrainsMono/{name}")  # a folder inside: unpacked flat
            info.size = len(data)
            tar.addfile(info, io.BytesIO(data))
    return path


def test_unpack_takes_only_the_files_used(tmp_path: Path) -> None:
    names = [*ui_fonts.FILES, ui_fonts.LICENSE, "JetBrainsMonoNerdFont-Thin.ttf", "README.md"]
    out = tmp_path / "out"
    out.mkdir()
    ui_fonts._unpack(_archive(tmp_path / "a.tar.xz", names), out)
    assert sorted(path.name for path in out.iterdir()) == sorted([*ui_fonts.FILES, ui_fonts.LICENSE])


def test_unpack_refuses_an_archive_missing_a_file(tmp_path: Path, capsys: pytest.CaptureFixture[str]) -> None:
    archive = _archive(tmp_path / "a.tar.xz", [ui_fonts.LICENSE, "JetBrainsMonoNerdFont-Regular.ttf"])
    with pytest.raises(typer.Exit):
        ui_fonts._unpack(archive, tmp_path)
    assert "JetBrainsMonoNerdFont-Bold.ttf" in capsys.readouterr().err


def test_to_woff2_keeps_every_glyph(tmp_path: Path) -> None:
    # round trip through the bundled file: back to TTF, then to woff2 again
    bundled = ui_fonts.FONTS_DIR / "JetBrainsMonoNerdFont-Regular.woff2"
    ttf = tmp_path / "f.ttf"
    font = TTFont(bundled)
    font.flavor = None
    font.save(ttf)
    ui_fonts.to_woff2(ttf, tmp_path / "f.woff2")
    again = TTFont(tmp_path / "f.woff2")
    assert again.flavor == "woff2"
    assert 0xF0674 in again.getBestCmap()  # the AI's icon (nf-md-creation)


def test_nothing_to_do_when_already_bundled(
    monkeypatch: pytest.MonkeyPatch, capsys: pytest.CaptureFixture[str]
) -> None:
    def no_requests(*_: object, **__: object) -> bytes:
        raise AssertionError("no request expected")

    monkeypatch.setattr(ui_fonts, "_get", no_requests)
    ui_fonts.update_fonts(ui_fonts.bundled_version())
    assert "nothing to do" in capsys.readouterr().out
